import{_ as c,C as l,o as s,c as h,a8 as a,b as r,w as t,a as o,E as d,a9 as n}from"./chunks/framework.DB1tY2mn.js";const p="/dochub/mermaid/assets/dev-explorer.DsWCHZJb.png",w=JSON.parse('{"title":"E2E Test Suite: Tiers, Folders, and CI","description":"","frontmatter":{"editLink":"https://github.com/mermaid-js/mermaid/edit/develop/packages/mermaid/src/docs/community/e2e-tests.md","head":[["link",{"rel":"canonical","href":"https://mermaid.ai/open-source/community/e2e-tests.html"}]]},"headers":[],"relativePath":"community/e2e-tests.md","filePath":"community/e2e-tests.md"}'),u={name:"community/e2e-tests.md"};function g(m,e,y,k,f,b){const i=l("Mermaid");return s(),h("div",null,[e[2]||(e[2]=a('<h1 id="e2e-test-suite-tiers-folders-and-ci" tabindex="-1">E2E Test Suite: Tiers, Folders, and CI <a class="header-anchor" href="#e2e-test-suite-tiers-folders-and-ci" aria-label="Permalink to &quot;E2E Test Suite: Tiers, Folders, and CI&quot;">​</a></h1><p>This is a contributor-facing manual for the <code>e2e/</code> test suite&#39;s tier structure — why it exists, how it&#39;s organized, which flags/labels control it, and how to work with it locally.</p><h2 id="why-this-exists" tabindex="-1">Why this exists <a class="header-anchor" href="#why-this-exists" aria-label="Permalink to &quot;Why this exists&quot;">​</a></h2><p>Before this restructuring, every PR ran the entire e2e suite — every diagram, every theme variant, every look/handdrawn combination — on every push. That&#39;s thorough, but it&#39;s expensive in two ways that scale badly as the suite grows:</p><ul><li><strong>CI time.</strong> A full run takes significantly longer than most PRs actually need. Most changes touch one diagram type; waiting on a full 8-shard run to validate a one-line fix is slow feedback for no real benefit.</li><li><strong>Argos quota.</strong> Every full run captures and uploads a screenshot for every diagram fixture, whether or not that fixture has anything to do with the change under review. Visual-regression services bill (or rate-limit) by build/screenshot volume, so an oversized &quot;safety net&quot; run on every push burns through quota fast.</li></ul><p>The fix is to split fixtures and specs into <strong>tiers</strong> — a small, fast, curated set that runs on every PR by default, and larger, slower sets reserved for less frequent, higher-confidence checks (nightly, and before a release-bound merge).</p><p><strong>Measured impact</strong> (from a real before/after comparison on this fork, on 2026-09-24 — pulled directly from GitHub Actions run history for PR #7; treat this as a dated example, not a live-updating stat):</p><table tabindex="0"><thead><tr><th></th><th>Full suite (pre-tiering)</th><th><code>pr-check</code>-tier only</th></tr></thead><tbody><tr><td>Shards</td><td>8</td><td>2</td></tr><tr><td>Per-shard time</td><td>~15–18 min</td><td>~6–8 min</td></tr><tr><td>Total wall-clock</td><td>~31 min</td><td>~8 min</td></tr><tr><td>Total compute (shard-minutes)</td><td>~128</td><td>~14</td></tr></tbody></table><p>Roughly a <strong>4x reduction in wall-clock time</strong> and <strong>~90% less total CI compute</strong> for the common case — a PR that only needs the <code>pr-check</code> tier to validate its change. That tracks with the underlying fixture split: as of 2026-09-24, <code>pr-check</code> covered about 15% of all <code>.mmd</code> fixtures (312 of 2,136 — <code>nightly-check</code> held 1,375, <code>visual-check</code> held 449). These counts will grow over time; the proportions are the durable part.</p><h2 id="directory-layout" tabindex="-1">Directory layout <a class="header-anchor" href="#directory-layout" aria-label="Permalink to &quot;Directory layout&quot;">​</a></h2><p>Two parallel trees hold the suite&#39;s content:</p>',11)),(s(),r(n,null,{default:t(()=>[d(i,{id:"mermaid-100",showCode:!0,graph:"flowchart%20TD%0A%20%20subgraph%20diagrams%5B%22e2e%2Fdiagrams%2F%3Cdiagram-type%3E%2F%22%5D%0A%20%20%20%20direction%20LR%0A%20%20%20%20d_pr%5B%22pr-check%2F%3Cbr%2F%3E*.mmd%20fixtures%22%5D%0A%20%20%20%20d_nightly%5B%22nightly-check%2F%3Cbr%2F%3E*.mmd%20fixtures%22%5D%0A%20%20%20%20d_visual%5B%22visual-check%2F%3Cbr%2F%3E*.mmd%20fixtures%22%5D%0A%20%20end%0A%20%20subgraph%20rendering%5B%22e2e%2Frendering%2F%3Cdiagram-type%3E%2F%22%5D%0A%20%20%20%20direction%20LR%0A%20%20%20%20r_pr%5B%22pr-check%2F%3Cbr%2F%3E*.spec.ts%22%5D%0A%20%20%20%20r_nightly%5B%22nightly-check%2F%3Cbr%2F%3E*.spec.ts%22%5D%0A%20%20%20%20r_visual%5B%22visual-check%2F%3Cbr%2F%3E*.spec.ts%22%5D%0A%20%20end%0A%20%20runner%5B%22e2e%2Frendering%2Fmmd-snapshots.spec.ts%3Cbr%2F%3E(global%20fixture%20runner)%22%5D%0A%20%20diagrams%20--%3E%7Cdiscovered%20%26%20rendered%20by%7C%20runner%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a('<ul><li><strong><code>e2e/diagrams/&lt;diagram-type&gt;/&lt;tier&gt;/*.mmd</code></strong> — static Mermaid source fixtures. Each one is just a diagram (optionally with YAML frontmatter setting <code>config</code>/<code>title</code>/a <code>description</code>). They aren&#39;t run directly; a single global spec, <code>e2e/rendering/mmd-snapshots.spec.ts</code>, discovers every <code>.mmd</code> file under <code>e2e/diagrams/</code>, registers one Playwright test per fixture (grouped into <code>describe</code> blocks mirroring the folder path), and renders it. This is where the large majority of diagram-rendering coverage lives — no test-writing required, just add a <code>.mmd</code> file in the right tier folder.</li><li><strong><code>e2e/rendering/&lt;diagram-type&gt;/&lt;tier&gt;/*.spec.{js,ts}</code></strong> — hand-written Playwright specs, for anything a static fixture can&#39;t express: DOM/CSS assertions, <code>.click()</code> interactions, directive-vs-<code>initialize()</code> precedence checks, multi-diagram array tests, custom <code>mermaid.initialize()</code> config, and similar. If your test needs to assert on rendered output beyond &quot;did it render without erroring,&quot; it belongs here instead of as a fixture.</li><li><strong><code>e2e/other/&lt;tier&gt;/*.spec.{js,ts}</code></strong> — cross-cutting specs that aren&#39;t about any single diagram type (XSS/security tests, GHSA regression tests, <code>iife</code>/embed tests, page-interaction tests, external-diagram loading). Only <code>pr-check/</code> is populated today.</li><li><strong><code>e2e/helpers/</code></strong> — shared test infrastructure: <code>util.ts</code> (the <code>imgSnapshotTest</code>/<code>renderGraph</code>/<code>verifyScreenshot</code> helpers every spec uses) and <code>mmd-snapshots.ts</code> (fixture discovery/metadata for the global runner).</li></ul><p>Not every <code>&lt;diagram-type&gt;/&lt;tier&gt;/</code> directory has content yet — some are intentionally empty, left in place as containers for tests that haven&#39;t been written. An empty tier folder isn&#39;t stray or safe to delete; it&#39;s scaffolding for the layout above, matching a diagram type or tier that&#39;s expected to gain coverage later.</p><h3 id="the-three-tiers" tabindex="-1">The three tiers <a class="header-anchor" href="#the-three-tiers" aria-label="Permalink to &quot;The three tiers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tier</th><th>Intent</th><th>Runs on</th></tr></thead><tbody><tr><td><code>pr-check</code></td><td>Small, curated, fast smoke set — one or two representative fixtures per feature, not an exhaustive sweep.</td><td>Every PR (see below), plus a <code>develop</code> merge, plus every nightly run.</td></tr><tr><td><code>nightly-check</code></td><td>Bulk/comprehensive coverage — most of the fixture volume lives here.</td><td>Once every 24h, plus a <code>master</code>-bound PR/merge (alongside <code>pr-check</code>).</td></tr><tr><td><code>visual-check</code></td><td>Theme/look (<code>classic</code>/<code>neo</code>/<code>handDrawn</code>)/layout/direction combinatorial sweeps — the same diagram rendered across every variant. Pixel/appearance content, not parse-only.</td><td>Not part of any automated CI gate. Reviewed manually via Applitools as a release-process step (<code>e2e-applitools.yml</code>, <code>workflow_dispatch</code>-only).</td></tr></tbody></table><p>A fixture or spec&#39;s tier is purely a function of which subfolder it lives in — there&#39;s no separate registry or config file to update.</p><p>If you&#39;re new to this structure, here&#39;s how to decide where a new test belongs:</p><ul><li><strong>Adding a new diagram feature or syntax?</strong> Add one small <code>pr-check</code> fixture covering the happy path — this is what every PR runs, so it catches an obvious regression immediately. If the feature has several meaningfully different shapes/variants/edge cases worth covering, add those as additional fixtures under <code>nightly-check</code> instead of piling them all into <code>pr-check</code> — <code>pr-check</code> is meant to stay small and fast, not become exhaustive.</li><li><strong>Fixing a rendering bug?</strong> Add a <code>pr-check</code> fixture that reproduces the bug (the minimal diagram that triggered it), so this exact regression is caught on every future PR. Only drop it into <code>nightly-check</code> instead if it&#39;s a narrow, rarely-hit edge case where running it on every PR isn&#39;t worth the extra time.</li><li><strong>Backfilling broad coverage for something that already works</strong> (e.g. every node-shape × edge-type combination, a sweep of config options)? That bulk volume belongs in <code>nightly-check</code> — it&#39;s comprehensive by design and only needs to run once a day, not on every push.</li><li><strong>Testing a purely visual/appearance difference</strong> — how a diagram looks under a different theme, <code>handDrawn</code> look, layout direction, or similar, where the underlying structure/parsing is unaffected? That&#39;s <code>visual-check</code>. It&#39;s pixel/appearance content reviewed by a human via Applitools, not something an automated parse-only assertion can usefully judge.</li><li><strong>Does your test need to assert on something beyond &quot;did it render without erroring&quot;?</strong> — a DOM/CSS assertion, a <code>.click()</code> interaction, directive-vs-<code>initialize()</code> precedence, a multi-diagram array, custom <code>mermaid.initialize()</code> config — that can&#39;t be expressed as a static <code>.mmd</code> fixture. Write a hand-written spec instead, under <code>e2e/rendering/&lt;diagram-type&gt;/&lt;tier&gt;/*.spec.{js,ts}</code> if it&#39;s about one specific diagram type, or <code>e2e/other/&lt;tier&gt;/*.spec.{js,ts}</code> if it&#39;s cross-cutting (security/XSS, embed/<code>iife</code>, page interactions, external-diagram loading, and similar). The same tier logic above still applies to these — a fast smoke-test spec goes in <code>pr-check</code>, a more exhaustive one in <code>nightly-check</code>.</li></ul><p>When in doubt, default to <code>pr-check</code> for anything a feature&#39;s author would want caught immediately, and move broader/slower coverage to <code>nightly-check</code>.</p><h2 id="how-ci-decides-what-to-run" tabindex="-1">How CI decides what to run <a class="header-anchor" href="#how-ci-decides-what-to-run" aria-label="Permalink to &quot;How CI decides what to run&quot;">​</a></h2>',9)),(s(),r(n,null,{default:t(()=>[d(i,{id:"mermaid-218",showCode:!0,graph:"flowchart%20TD%0A%20%20start%7B%22What%20triggered%20this%20run%3F%22%7D%0A%20%20start%20--%3E%7C%22PR%20%E2%86%92%20develop%22%7C%20pr_label%7B%22'run%20pr%20tests'%3Cbr%2F%3Elabel%20set%3F%22%7D%0A%20%20start%20--%3E%7C%22PR%20%E2%86%92%20master%22%7C%20release_label%7B%22'run%20release%20test'%3Cbr%2F%3Elabel%20set%3F%22%7D%0A%20%20start%20--%3E%7C%22Push%20to%20develop%3Cbr%2F%3E(e.g.%20a%20PR%20merge)%22%7C%20push_develop%5B%22pr-check%20tier%20only%22%5D%0A%20%20start%20--%3E%7C%22Push%20to%20master%22%7C%20push_master%5B%22pr-check%20%2B%20nightly-check%20tiers%22%5D%0A%20%20start%20--%3E%7C%22Scheduled%20(daily)%20or%3Cbr%2F%3Emanual%20'simulated%20nightly'%22%7C%20nightly_run%5B%22pr-check%20%2B%20nightly-check%20tiers%22%5D%0A%0A%20%20pr_label%20--%3E%7Cyes%2C%20or%20PR%20just%20opened%7C%20pr_scoped%5B%22pr-check%20tier%20only%22%5D%0A%20%20pr_label%20--%3E%7Cno%7C%20blocked1%5B%22e2e%20skipped%20%E2%80%94%3Cbr%2F%3Erequired%20check%20fails%22%5D%0A%0A%20%20release_label%20--%3E%7Cyes%2C%20or%20PR%20just%20opened%7C%20gated%5B%22pr-check%20%2B%20nightly-check%20tiers%3Cbr%2F%3E(visual-check%20excluded%20%E2%80%94%20see%20Applitools)%22%5D%0A%20%20release_label%20--%3E%7Cno%7C%20blocked2%5B%22e2e%20skipped%20%E2%80%94%3Cbr%2F%3Erequired%20check%20fails%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=a(`<p>Both labels — <code>run pr tests</code> and <code>run release test</code> — default to <strong>on</strong>: a small automation job adds them to every freshly-opened PR (targeting <code>develop</code> and <code>master</code> respectively). Removing the label before a later push causes e2e to be skipped for that push, which is treated as a <strong>failure</strong> of the required status check (not a silent pass) — merging is still possible via a repo admin&#39;s branch-protection bypass, but it&#39;s not a default-open door.</p><p>Note that <code>run release test</code> — despite its name — does <strong>not</strong> gate the <code>visual-check</code> tier. <code>visual-check</code> is theme/look/layout/direction combinatorial sweeps: pixel/appearance content that&#39;s better judged by a human during the manual Applitools pass (<code>e2e-applitools.yml</code>) than by an automated parse-only check here. The label name is a holdover from before this tier split; renaming it is tracked separately and out of scope for this doc.</p><p>This label-gating logic, and the nightly/scheduled workflow, are <strong>upstream-only</strong> — every branch of this logic is guarded by a check that it&#39;s running on <code>mermaid-js/mermaid</code>, not a fork. On a fork, e2e.yml falls back to its original full-suite/diff-based-scoping behavior, and the nightly workflow&#39;s own job is a no-op (there&#39;s no Argos project/credentials there to make screenshot capture worthwhile).</p><h2 id="flags-and-environment-variables" tabindex="-1">Flags and environment variables <a class="header-anchor" href="#flags-and-environment-variables" aria-label="Permalink to &quot;Flags and environment variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Where</th><th>Effect</th></tr></thead><tbody><tr><td><code>MERMAID_E2E_FIXTURE_TIER</code></td><td>env var, read by <code>mmd-snapshots.spec.ts</code></td><td>Comma-separated tier list (e.g. <code>pr-check</code>, or <code>pr-check,nightly-check</code>) that narrows which <code>.mmd</code> fixtures get registered. Unset = every tier.</td></tr><tr><td><code>run pr tests</code></td><td>GitHub PR label</td><td>Gates whether a <code>develop</code>-bound PR&#39;s e2e run happens at all (scoped to <code>pr-check</code> tier when present). Defaults on for new PRs.</td></tr><tr><td><code>run release test</code></td><td>GitHub PR label</td><td>Same, for <code>master</code>-bound PRs (scoped to <code>pr-check</code>+<code>nightly-check</code> — <code>visual-check</code> excluded, see above). Defaults on for new PRs.</td></tr><tr><td><code>E2E_SCOPE_BY_DIAGRAM</code></td><td>repo variable</td><td>Kill-switch for the (separate, older) diagram-diff-based scoping used outside the tier-gating paths. Set to <code>&#39;false&#39;</code> to force the full suite unconditionally.</td></tr><tr><td><code>RUN_VISUAL_TEST</code></td><td>computed CI env var</td><td>Controls whether screenshots get captured for Argos upload. Only ever true on the real upstream repo — never on this fork.</td></tr><tr><td><code>USE_APPLI</code></td><td>env var</td><td>Switches screenshot verification to Applitools instead of the Argos/local-snapshot path. Common in personal dev shells — remember to override it (<code>USE_APPLI=</code>) when you specifically want the Argos code path locally.</td></tr><tr><td><code>SCREENSHOT_DIR</code></td><td>env var</td><td>Overrides where Argos-mode screenshots get written locally. Defaults to <code>e2e/screenshots</code>.</td></tr><tr><td><code>GROUP_ARGOS_IMAGES</code> / <code>group_argos_images</code></td><td>computed CI env var / <code>workflow_dispatch</code> input</td><td>Whether screenshots get composited into per-folder &quot;sheets&quot; before Argos upload, versus uploaded individually.</td></tr><tr><td><code>MERMAID_DEV_EXPLORER_ROOT</code></td><td>env var, read by <code>.esbuild/server.ts</code></td><td>Which <code>.mmd</code> root the local Dev Explorer (<code>/dev</code> route) serves. Defaults to <code>e2e</code> (the whole tree — fixtures, platform diagrams, everything).</td></tr><tr><td><code>MERMAID_PORT</code> / <code>MERMAID_DEV_PORT</code></td><td>env var</td><td>Overrides the dev server port Playwright/the dev server use.</td></tr><tr><td><code>E2E_COVERAGE</code></td><td>env var</td><td>Switches the dev server to the coverage-instrumented build, and enables native V8 coverage collection during a Playwright run.</td></tr></tbody></table><h2 id="working-with-tiers-locally" tabindex="-1">Working with tiers locally <a class="header-anchor" href="#working-with-tiers-locally" aria-label="Permalink to &quot;Working with tiers locally&quot;">​</a></h2><p><strong>Run only the <code>pr-check</code> tier</strong> (mirrors what a PR&#39;s CI actually runs):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MERMAID_E2E_FIXTURE_TIER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pr-check</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> e2e/rendering/mmd-snapshots.spec.ts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/e2e-tier-scope.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pr-check</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;,&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39; &#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p><strong>Run a &quot;simulated nightly&quot; (<code>pr-check</code>+<code>nightly-check</code>)</strong> without waiting for the schedule:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Nightly E2E&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mermaid-js/mermaid</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or purely locally, no CI involved:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MERMAID_E2E_FIXTURE_TIER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pr-check,nightly-check</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> e2e/rendering/mmd-snapshots.spec.ts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/e2e-tier-scope.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pr-check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nightly-check</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;,&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39; &#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p><strong>See what a fixture would look like in Argos</strong>, without needing real Argos credentials or touching any baseline: capture screenshots locally with <code>RUN_VISUAL_TEST=true</code> (remembering to clear <code>USE_APPLI</code> if it&#39;s set in your shell), then either browse <code>e2e/screenshots/</code> directly, or run <code>pnpm run screenshots:sheets</code> to composite them the same way CI does before upload.</p><p><strong>Run the <code>visual-check</code> tier</strong>: start the local dev server first (<code>pnpm dev</code>, in its own terminal) — the suite is large enough (900+ tests) that it&#39;s worth having it already warm rather than waiting on Playwright&#39;s own <code>webServer</code> auto-start/cold build on the first request:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright:visual-check</span></span></code></pre></div><p>This isn&#39;t something you&#39;d run as part of routine local development — it&#39;s only used when preparing a release, alongside the manual Applitools pass described in the tier table above. It runs both halves of the tier unconditionally (one does not get skipped if the other has a failure): the <code>.mmd</code> fixtures under every <code>e2e/diagrams/&lt;diagram-type&gt;/visual-check/</code> folder (via the global <code>mmd-snapshots.spec.ts</code> runner, selected by test title) and the hand-written specs under <code>e2e/rendering/&lt;diagram-type&gt;/visual-check/*.spec.ts</code> (selected by file path; currently only populated under <code>common-tests/</code>).</p><h2 id="diagrams-and-screenshots" tabindex="-1">Diagrams and screenshots <a class="header-anchor" href="#diagrams-and-screenshots" aria-label="Permalink to &quot;Diagrams and screenshots&quot;">​</a></h2><p>The Dev Explorer (<code>/dev</code> route) — browse <code>.mmd</code> fixtures under the configured <code>MERMAID_DEV_EXPLORER_ROOT</code> and preview them rendered:</p><p><img src="`+p+'" alt="Dev Explorer root view, showing the top-level e2e folder listing"></p><blockquote><p>📸 <strong>Placeholder — add screenshots here:</strong></p><ul><li>The GitHub PR &quot;Checks&quot; tab, side by side: a <code>develop</code>-bound PR showing the scoped 2-shard <code>pr-check</code>-tier run, versus a <code>master</code>-bound PR showing the scoped 4-shard <code>pr-check</code>+<code>nightly-check</code> run (<code>visual-check</code> excluded).</li><li>The &quot;Nightly E2E&quot; entry in the Actions tab, filtered, showing a recent scheduled run&#39;s result.</li></ul></blockquote><p>The flowcharts above (directory layout, CI decision flow) are Mermaid diagrams — edit them the same way you&#39;d edit any diagram in this repo. If you add more diagrams to this doc, prefer Mermaid over static images where the content is structural/flow-based (it stays accurate as the suite evolves, and — fittingly for this repo — is easy for any contributor to update in a plain-text diff).</p>',19))])}const E=c(u,[["render",g]]);export{w as __pageData,E as default};
